SELECT 
    (100 * (LEAST(
        (
            SELECT T2.fastestLapTime FROM results AS T1 JOIN results AS T2 ON T1.raceId = T2.raceId AND T1.driverId = T2.driverId WHERE T1.raceId = 2008 AND T1.positionText = 'Last' AND T1.number = 3
