        ) / 
            (
                SELECT T1.time FROM results AS T1 JOIN races AS T2 ON T1.raceId = T2.raceId WHERE T1.raceId = 2008 AND T1.statusId = (SELECT statusId FROM status WHERE status = 'Finished') AND T1.number = 3
            )
    )) AS faster_percentage
FROM results 
WHERE raceId = 2008 AND number = 3 AND positionText = 'Champion'

