SELECT 
    (SELECT SUM(cost) FROM expense WHERE link_to_budget IN (
        SELECT budget_id FROM budget WHERE event_status = 'Open' AND amount > 0 AND category = 'food'
    )) AS total_cost,
    (SELECT cost FROM expense WHERE link_to_budget IN (
        SELECT budget_id FROM budget WHERE event_status = 'Open' AND amount > 0 AND category = 'food' AND link_to_event = 'Yearly Kickoff'
    )) AS yearly_kickoff_cost,
    ((SELECT cost FROM expense WHERE link_to_budget IN (
        SELECT budget_id FROM budget WHERE event_status = 'Open' AND amount > 0 AND category = 'food' AND link_to_event = 'Yearly Kickoff'
    )) * 100) / (SELECT SUM(cost) FROM expense WHERE link_to_budget IN (
        SELECT budget_id FROM budget WHERE event_status = 'Open' AND amount > 0 AND category = 'food'
    )) AS yearly_kickoff_percentage

